using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Retrieves an application setting by key.")]
    public static string GetSetting(
        [Description("The setting key to look up (e.g. 'MaxRetries', 'Timeout')")] string key)
    {
        var settings = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["MaxRetries"] = "3",
            ["Timeout"] = "30s",
            ["Environment"] = "Production",
            ["LogLevel"] = "Information"
        };

        return settings.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Setting '{key}' not found.";
    }

    [McpServerTool, Description("Lists all available application setting keys.")]
    public static string ListSettings() =>
        string.Join(", ", "MaxRetries", "Timeout", "Environment", "LogLevel");
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(new
        {
            MaxRetries = 3,
            Timeout = "30s",
            Environment = "Production",
            LogLevel = "Information",
            Features = new { DarkMode = true, BetaAccess = false }
        }, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(
        UriTemplate = "config://features",
        Name = "Feature Flags",
        MimeType = "application/json"),
     Description("Returns current feature flag settings.")]
    public static string GetFeatureFlags() =>
        JsonSerializer.Serialize(new
        {
            DarkMode = true,
            BetaAccess = false,
            NewDashboard = true,
            ApiV2 = false
        }, new JsonSerializerOptions { WriteIndented = true });
}

